package clusterdata.datatypes;

import java.io.Serializable;

public class TaskEvent implements Serializable {

    public static final int SUBMIT = 0;
    public static final int SCHEDULE = 1;
    public static final int EVICT = 2;
    public static final int FAIL = 3;
    public static final int FINISH = 4;
    public static final int KILL = 5;
    public static final int LOST = 6;
    public static final int UPDATE_PENDING = 7;
    public static final int UPDATE_RUNNING = 8;

    public long timestamp;
    public String missingInfo;
    public long jobId;
    public int taskIndex;
    public long machineId;
    public int eventType;
    public String user;
    public int schedulingClass;
    public int priority;
    public double cpuRequest;
    public double memoryRequest;
    public double diskSpaceRequest;
    public int differentMachinesConstraint;

    public TaskEvent() {}

    public static TaskEvent fromCsv(String line) {
        String[] fields = line.split(",", -1);
        if (fields.length < 13) {
            return null;
        }
        try {
            TaskEvent event = new TaskEvent();
            event.timestamp = fields[0].isEmpty() ? 0L : Long.parseLong(fields[0]);
            event.missingInfo = fields[1];
            event.jobId = fields[2].isEmpty() ? 0L : Long.parseLong(fields[2]);
            event.taskIndex = fields[3].isEmpty() ? 0 : Integer.parseInt(fields[3]);
            event.machineId = fields[4].isEmpty() ? 0L : Long.parseLong(fields[4]);
            event.eventType = fields[5].isEmpty() ? -1 : Integer.parseInt(fields[5]);
            event.user = fields[6];
            event.schedulingClass = fields[7].isEmpty() ? 0 : Integer.parseInt(fields[7]);
            event.priority = fields[8].isEmpty() ? 0 : Integer.parseInt(fields[8]);
            event.cpuRequest = fields[9].isEmpty() ? 0.0 : Double.parseDouble(fields[9]);
            event.memoryRequest = fields[10].isEmpty() ? 0.0 : Double.parseDouble(fields[10]);
            event.diskSpaceRequest = fields[11].isEmpty() ? 0.0 : Double.parseDouble(fields[11]);
            event.differentMachinesConstraint = fields[12].isEmpty() ? 0 : Integer.parseInt(fields[12]);
            return event;
        } catch (NumberFormatException e) {
            return null;
        }
    }

    public long getTimestamp() {
        return timestamp;
    }

    public long getJobId() {
        return jobId;
    }

    public int getEventType() {
        return eventType;
    }

    @Override
    public String toString() {
